# Why depth helps: a linear model vs 1 and 2 hidden layers on a non-linear problem (NumPy MLP)
import numpy as np
rng = np.random.default_rng(0)
def circles(n):
    r = np.r_[rng.uniform(0, 1, n // 2), rng.uniform(1.5, 2.5, n // 2)]; a = rng.uniform(0, 2 * np.pi, n)
    return np.c_[r * np.cos(a), r * np.sin(a)] + rng.normal(0, 0.15, (n, 2)), np.r_[np.ones(n // 2), np.zeros(n // 2)]
Xtr, ytr = circles(400); Xte, yte = circles(400)
def train(hidden, epochs=3000, lr=0.5):
    sizes = [2] + hidden + [1]; W = [rng.normal(0, 1 / np.sqrt(a), (a, b)) for a, b in zip(sizes, sizes[1:])]; B = [np.zeros(b) for b in sizes[1:]]
    def forward(X):
        H = [X]
        for i in range(len(W)): Zl = H[-1] @ W[i] + B[i]; H.append(np.tanh(Zl) if i < len(W) - 1 else 1 / (1 + np.exp(-Zl)))
        return H
    for _ in range(epochs):
        H = forward(Xtr); G = (H[-1][:, 0] - ytr)[:, None] / len(Xtr)
        for i in reversed(range(len(W))):
            gW, gB = H[i].T @ G, G.sum(0)
            if i: G = (G @ W[i].T) * (1 - H[i] ** 2)
            W[i] -= lr * gW; B[i] -= lr * gB
    acc = lambda X, y: ((forward(X)[-1][:, 0] > 0.5) == y).mean()
    return acc(Xtr, ytr), acc(Xte, yte), sum(w.size for w in W) + sum(b.size for b in B)
for h in ([], [4], [8, 8]):
    tr, te, p = train(h); print(f"hidden layers {str(h):7s} params {p:3d}  train acc {tr:.3f}  test acc {te:.3f}")
